// SUL-InformationExtIEs ::= OBJECT SET OF F1AP-PROTOCOL-EXTENSION
uint32_t sul_info_ext_ies_o::idx_to_id(uint32_t idx)
{
  static const uint32_t names[] = {354, 356};
  return map_enum_number(names, 2, idx, "id");
}
bool sul_info_ext_ies_o::is_id_valid(const uint32_t& id)
{
  static const uint32_t names[] = {354, 356};
  for (const auto& o : names) {
    if (o == id) {
      return true;
    }
  }
  return false;
}
crit_e sul_info_ext_ies_o::get_crit(const uint32_t& id)
{
  switch (id) {
    case 354:
      return crit_e::ignore;
    case 356:
      return crit_e::ignore;
    default:
      asn1::log_error("The id={} is not recognized", id);
  }
  return {};
}
presence_e sul_info_ext_ies_o::get_presence(const uint32_t& id)
{
  switch (id) {
    case 354:
      return presence_e::optional;
    case 356:
      return presence_e::optional;
    default:
      asn1::log_error("The id={} is not recognized", id);
  }
  return {};
}

OCUDUASN_CODE sul_info_ext_ies_container::pack(bit_ref& bref) const
{
  uint32_t nof_ies = 0;
  nof_ies += carrier_list_present ? 1 : 0;
  nof_ies += freq_shift7p5khz_present ? 1 : 0;
  HANDLE_CODE(pack_length(bref, nof_ies, 1u, 65535u, true));

  if (carrier_list_present) {
    HANDLE_CODE(pack_ie(bref, 354, crit_e{crit_e::ignore}, [this, &bref]() {
      return pack_dyn_seq_of(bref, carrier_list, 1, 5, true);
    }));
  }
  if (freq_shift7p5khz_present) {
    HANDLE_CODE(pack_ie(bref, 356, crit_e{crit_e::ignore}, [this, &bref]() { return freq_shift7p5khz.pack(bref); }));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE sul_info_ext_ies_container::unpack(cbit_ref& bref)
{
  uint32_t nof_ies = 0;
  HANDLE_CODE(unpack_length(nof_ies, bref, 1u, 65535u, true));

  for (; nof_ies > 0; --nof_ies) {
    uint32_t id;
    crit_e   crit;
    HANDLE_CODE(unpack_ie_header(bref, id, crit, &sul_info_ext_ies_o::get_crit));

    switch (id) {
      case 354: {
        carrier_list_present = true;
        HANDLE_CODE(
            unpack_ie_value(bref, [this, &bref]() { return unpack_dyn_seq_of(carrier_list, bref, 1, 5, true); }));
        break;
      }
      case 356: {
        freq_shift7p5khz_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() { return freq_shift7p5khz.unpack(bref); }));
        break;
      }
      default:
        HANDLE_CODE(skip_ignored_ie(bref, crit, id));
        break;
    }
  }

  return OCUDUASN_SUCCESS;
}
void sul_info_ext_ies_container::to_json(json_writer& j) const
{
  j.start_array();
  if (carrier_list_present) {
    j.start_obj();
    j.write_int("id", 354);
    j.write_str("criticality", "ignore");
    j.start_array("extensionValue");
    for (const auto& e1 : carrier_list) {
      e1.to_json(j);
    }
    j.end_array();
    j.end_obj();
  }
  if (freq_shift7p5khz_present) {
    j.start_obj();
    j.write_int("id", 356);
    j.write_str("criticality", "ignore");
    j.write_str("extensionValue", freq_shift7p5khz.to_string());
    j.end_obj();
  }
  j.end_array();
}

