// PosSRSResource-Item-ExtIEs ::= OBJECT SET OF F1AP-PROTOCOL-EXTENSION
uint32_t pos_srs_res_item_ext_ies_o::idx_to_id(uint32_t idx)
{
  static const uint32_t names[] = {820};
  return map_enum_number(names, 1, idx, "id");
}
bool pos_srs_res_item_ext_ies_o::is_id_valid(const uint32_t& id)
{
  return 820 == id;
}
crit_e pos_srs_res_item_ext_ies_o::get_crit(const uint32_t& id)
{
  if (id == 820) {
    return crit_e::ignore;
  }
  asn1::log_error("The id={} is not recognized", id);
  return {};
}
presence_e pos_srs_res_item_ext_ies_o::get_presence(const uint32_t& id)
{
  if (id == 820) {
    return presence_e::optional;
  }
  asn1::log_error("The id={} is not recognized", id);
  return {};
}

OCUDUASN_CODE pos_srs_res_item_ext_ies_container::pack(bit_ref& bref) const
{
  uint32_t nof_ies = 0;
  nof_ies += tx_hop_cfg_present ? 1 : 0;
  HANDLE_CODE(pack_length(bref, nof_ies, 1u, 65535u, true));

  if (tx_hop_cfg_present) {
    HANDLE_CODE(pack_ie(bref, 820, crit_e{crit_e::ignore}, [this, &bref]() { return tx_hop_cfg.pack(bref); }));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE pos_srs_res_item_ext_ies_container::unpack(cbit_ref& bref)
{
  uint32_t nof_ies = 0;
  HANDLE_CODE(unpack_length(nof_ies, bref, 1u, 65535u, true));

  for (; nof_ies > 0; --nof_ies) {
    uint32_t id;
    crit_e   crit;
    HANDLE_CODE(unpack_ie_header(bref, id, crit, &pos_srs_res_item_ext_ies_o::get_crit));

    if (id == 820) {
      {
        tx_hop_cfg_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() { return tx_hop_cfg.unpack(bref); }));
      }
    } else {
      HANDLE_CODE(skip_ignored_ie(bref, crit, id));
    }
  }

  return OCUDUASN_SUCCESS;
}
void pos_srs_res_item_ext_ies_container::to_json(json_writer& j) const
{
  j.start_array();
  if (tx_hop_cfg_present) {
    j.start_obj();
    j.write_int("id", 820);
    j.write_str("criticality", "ignore");
    j.write_fieldname("extensionValue");
    tx_hop_cfg.to_json(j);
    j.end_obj();
  }
  j.end_array();
}

