// AdditionalPath-Item-ExtIEs ::= OBJECT SET OF F1AP-PROTOCOL-EXTENSION
uint32_t add_path_item_ext_ies_o::idx_to_id(uint32_t idx)
{
  static const uint32_t names[] = {558, 636};
  return map_enum_number(names, 2, idx, "id");
}
bool add_path_item_ext_ies_o::is_id_valid(const uint32_t& id)
{
  static const uint32_t names[] = {558, 636};
  for (const auto& o : names) {
    if (o == id) {
      return true;
    }
  }
  return false;
}
crit_e add_path_item_ext_ies_o::get_crit(const uint32_t& id)
{
  switch (id) {
    case 558:
      return crit_e::ignore;
    case 636:
      return crit_e::ignore;
    default:
      asn1::log_error("The id={} is not recognized", id);
  }
  return {};
}
presence_e add_path_item_ext_ies_o::get_presence(const uint32_t& id)
{
  switch (id) {
    case 558:
      return presence_e::optional;
    case 636:
      return presence_e::optional;
    default:
      asn1::log_error("The id={} is not recognized", id);
  }
  return {};
}

OCUDUASN_CODE add_path_item_ext_ies_container::pack(bit_ref& bref) const
{
  uint32_t nof_ies = 0;
  nof_ies += multiple_ul_ao_a_present ? 1 : 0;
  nof_ies += path_pwr_present ? 1 : 0;
  HANDLE_CODE(pack_length(bref, nof_ies, 1u, 65535u, true));

  if (multiple_ul_ao_a_present) {
    HANDLE_CODE(pack_ie(bref, 558, crit_e{crit_e::ignore}, [this, &bref]() { return multiple_ul_ao_a.pack(bref); }));
  }
  if (path_pwr_present) {
    HANDLE_CODE(pack_ie(bref, 636, crit_e{crit_e::ignore}, [this, &bref]() { return path_pwr.pack(bref); }));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE add_path_item_ext_ies_container::unpack(cbit_ref& bref)
{
  uint32_t nof_ies = 0;
  HANDLE_CODE(unpack_length(nof_ies, bref, 1u, 65535u, true));

  for (; nof_ies > 0; --nof_ies) {
    uint32_t id;
    crit_e   crit;
    HANDLE_CODE(unpack_ie_header(bref, id, crit, &add_path_item_ext_ies_o::get_crit));

    switch (id) {
      case 558: {
        multiple_ul_ao_a_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() { return multiple_ul_ao_a.unpack(bref); }));
        break;
      }
      case 636: {
        path_pwr_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() { return path_pwr.unpack(bref); }));
        break;
      }
      default:
        HANDLE_CODE(skip_ignored_ie(bref, crit, id));
        break;
    }
  }

  return OCUDUASN_SUCCESS;
}
void add_path_item_ext_ies_container::to_json(json_writer& j) const
{
  j.start_array();
  if (multiple_ul_ao_a_present) {
    j.start_obj();
    j.write_int("id", 558);
    j.write_str("criticality", "ignore");
    j.write_fieldname("extensionValue");
    multiple_ul_ao_a.to_json(j);
    j.end_obj();
  }
  if (path_pwr_present) {
    j.start_obj();
    j.write_int("id", 636);
    j.write_str("criticality", "ignore");
    j.write_fieldname("extensionValue");
    path_pwr.to_json(j);
    j.end_obj();
  }
  j.end_array();
}

