// Aggregated-PosSRS-Resource-ID-Item-ExtIEs ::= OBJECT SET OF F1AP-PROTOCOL-EXTENSION
uint32_t aggr_pos_srs_res_id_item_ext_ies_o::idx_to_id(uint32_t idx)
{
  static const uint32_t names[] = {839, 840, 841};
  return map_enum_number(names, 3, idx, "id");
}
bool aggr_pos_srs_res_id_item_ext_ies_o::is_id_valid(const uint32_t& id)
{
  static const uint32_t names[] = {839, 840, 841};
  for (const auto& o : names) {
    if (o == id) {
      return true;
    }
  }
  return false;
}
crit_e aggr_pos_srs_res_id_item_ext_ies_o::get_crit(const uint32_t& id)
{
  switch (id) {
    case 839:
      return crit_e::ignore;
    case 840:
      return crit_e::ignore;
    case 841:
      return crit_e::ignore;
    default:
      asn1::log_error("The id={} is not recognized", id);
  }
  return {};
}
presence_e aggr_pos_srs_res_id_item_ext_ies_o::get_presence(const uint32_t& id)
{
  switch (id) {
    case 839:
      return presence_e::mandatory;
    case 840:
      return presence_e::mandatory;
    case 841:
      return presence_e::optional;
    default:
      asn1::log_error("The id={} is not recognized", id);
  }
  return {};
}

OCUDUASN_CODE aggr_pos_srs_res_id_item_ext_ies_container::pack(bit_ref& bref) const
{
  uint32_t nof_ies = 2;
  nof_ies += nr_pci_present ? 1 : 0;
  HANDLE_CODE(pack_length(bref, nof_ies, 1u, 65535u, true));

  HANDLE_CODE(pack_ie(bref, 839, crit_e{crit_e::ignore}, [this, &bref]() {
    return pack_integer(bref, point_a, (uint32_t)0u, (uint32_t)3279165u, false, true);
  }));
  HANDLE_CODE(pack_ie(bref, 840, crit_e{crit_e::ignore}, [this, &bref]() { return scs_specific_carrier.pack(bref); }));
  if (nr_pci_present) {
    HANDLE_CODE(pack_ie(bref, 841, crit_e{crit_e::ignore}, [this, &bref]() {
      return pack_integer(bref, nr_pci, (uint16_t)0u, (uint16_t)1007u, false, true);
    }));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE aggr_pos_srs_res_id_item_ext_ies_container::unpack(cbit_ref& bref)
{
  uint32_t nof_ies = 0;
  HANDLE_CODE(unpack_length(nof_ies, bref, 1u, 65535u, true));

  uint32_t nof_mandatory_ies = 2;

  for (; nof_ies > 0; --nof_ies) {
    uint32_t id;
    crit_e   crit;
    HANDLE_CODE(unpack_ie_header(bref, id, crit, &aggr_pos_srs_res_id_item_ext_ies_o::get_crit));

    switch (id) {
      case 839: {
        nof_mandatory_ies--;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() {
          return unpack_integer(point_a, bref, (uint32_t)0u, (uint32_t)3279165u, false, true);
        }));
        break;
      }
      case 840: {
        nof_mandatory_ies--;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() { return scs_specific_carrier.unpack(bref); }));
        break;
      }
      case 841: {
        nr_pci_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() {
          return unpack_integer(nr_pci, bref, (uint16_t)0u, (uint16_t)1007u, false, true);
        }));
        break;
      }
      default:
        HANDLE_CODE(skip_ignored_ie(bref, crit, id));
        break;
    }
  }
  if (nof_mandatory_ies > 0) {
    asn1::log_error("Mandatory fields are missing\n");

    return OCUDUASN_ERROR_DECODE_FAIL;
  }
  return OCUDUASN_SUCCESS;
}
void aggr_pos_srs_res_id_item_ext_ies_container::to_json(json_writer& j) const
{
  j.start_array();
  j.start_obj();
  j.write_int("id", 839);
  j.write_str("criticality", "ignore");
  j.write_int("extensionValue", point_a);
  j.end_obj();
  j.start_obj();
  j.write_int("id", 840);
  j.write_str("criticality", "ignore");
  j.write_fieldname("extensionValue");
  scs_specific_carrier.to_json(j);
  j.end_obj();
  if (nr_pci_present) {
    j.start_obj();
    j.write_int("id", 841);
    j.write_str("criticality", "ignore");
    j.write_int("extensionValue", nr_pci);
    j.end_obj();
  }
  j.end_array();
}

