// IAB-MT-Cell-List-Item-ExtIEs ::= OBJECT SET OF F1AP-PROTOCOL-EXTENSION
uint32_t iab_mt_cell_list_item_ext_ies_o::idx_to_id(uint32_t idx)
{
  static const uint32_t names[] = {637, 638, 639, 640};
  return map_enum_number(names, 4, idx, "id");
}
bool iab_mt_cell_list_item_ext_ies_o::is_id_valid(const uint32_t& id)
{
  static const uint32_t names[] = {637, 638, 639, 640};
  for (const auto& o : names) {
    if (o == id) {
      return true;
    }
  }
  return false;
}
crit_e iab_mt_cell_list_item_ext_ies_o::get_crit(const uint32_t& id)
{
  switch (id) {
    case 637:
      return crit_e::ignore;
    case 638:
      return crit_e::ignore;
    case 639:
      return crit_e::ignore;
    case 640:
      return crit_e::ignore;
    default:
      asn1::log_error("The id={} is not recognized", id);
  }
  return {};
}
presence_e iab_mt_cell_list_item_ext_ies_o::get_presence(const uint32_t& id)
{
  switch (id) {
    case 637:
      return presence_e::optional;
    case 638:
      return presence_e::optional;
    case 639:
      return presence_e::optional;
    case 640:
      return presence_e::optional;
    default:
      asn1::log_error("The id={} is not recognized", id);
  }
  return {};
}

OCUDUASN_CODE iab_mt_cell_list_item_ext_ies_container::pack(bit_ref& bref) const
{
  uint32_t nof_ies = 0;
  nof_ies += du_rx_mt_rx_extend_present ? 1 : 0;
  nof_ies += du_tx_mt_tx_extend_present ? 1 : 0;
  nof_ies += du_rx_mt_tx_extend_present ? 1 : 0;
  nof_ies += du_tx_mt_rx_extend_present ? 1 : 0;
  HANDLE_CODE(pack_length(bref, nof_ies, 1u, 65535u, true));

  if (du_rx_mt_rx_extend_present) {
    HANDLE_CODE(pack_ie(bref, 637, crit_e{crit_e::ignore}, [this, &bref]() { return du_rx_mt_rx_extend.pack(bref); }));
  }
  if (du_tx_mt_tx_extend_present) {
    HANDLE_CODE(pack_ie(bref, 638, crit_e{crit_e::ignore}, [this, &bref]() { return du_tx_mt_tx_extend.pack(bref); }));
  }
  if (du_rx_mt_tx_extend_present) {
    HANDLE_CODE(pack_ie(bref, 639, crit_e{crit_e::ignore}, [this, &bref]() { return du_rx_mt_tx_extend.pack(bref); }));
  }
  if (du_tx_mt_rx_extend_present) {
    HANDLE_CODE(pack_ie(bref, 640, crit_e{crit_e::ignore}, [this, &bref]() { return du_tx_mt_rx_extend.pack(bref); }));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE iab_mt_cell_list_item_ext_ies_container::unpack(cbit_ref& bref)
{
  uint32_t nof_ies = 0;
  HANDLE_CODE(unpack_length(nof_ies, bref, 1u, 65535u, true));

  for (; nof_ies > 0; --nof_ies) {
    uint32_t id;
    crit_e   crit;
    HANDLE_CODE(unpack_ie_header(bref, id, crit, &iab_mt_cell_list_item_ext_ies_o::get_crit));

    switch (id) {
      case 637: {
        du_rx_mt_rx_extend_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() { return du_rx_mt_rx_extend.unpack(bref); }));
        break;
      }
      case 638: {
        du_tx_mt_tx_extend_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() { return du_tx_mt_tx_extend.unpack(bref); }));
        break;
      }
      case 639: {
        du_rx_mt_tx_extend_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() { return du_rx_mt_tx_extend.unpack(bref); }));
        break;
      }
      case 640: {
        du_tx_mt_rx_extend_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() { return du_tx_mt_rx_extend.unpack(bref); }));
        break;
      }
      default:
        HANDLE_CODE(skip_ignored_ie(bref, crit, id));
        break;
    }
  }

  return OCUDUASN_SUCCESS;
}
void iab_mt_cell_list_item_ext_ies_container::to_json(json_writer& j) const
{
  j.start_array();
  if (du_rx_mt_rx_extend_present) {
    j.start_obj();
    j.write_int("id", 637);
    j.write_str("criticality", "ignore");
    j.write_str("extensionValue", du_rx_mt_rx_extend.to_string());
    j.end_obj();
  }
  if (du_tx_mt_tx_extend_present) {
    j.start_obj();
    j.write_int("id", 638);
    j.write_str("criticality", "ignore");
    j.write_str("extensionValue", du_tx_mt_tx_extend.to_string());
    j.end_obj();
  }
  if (du_rx_mt_tx_extend_present) {
    j.start_obj();
    j.write_int("id", 639);
    j.write_str("criticality", "ignore");
    j.write_str("extensionValue", du_rx_mt_tx_extend.to_string());
    j.end_obj();
  }
  if (du_tx_mt_rx_extend_present) {
    j.start_obj();
    j.write_int("id", 640);
    j.write_str("criticality", "ignore");
    j.write_str("extensionValue", du_tx_mt_rx_extend.to_string());
    j.end_obj();
  }
  j.end_array();
}

