// ConditionalIntraDUMobilityInformation-ExtIEs ::= OBJECT SET OF F1AP-PROTOCOL-EXTENSION
uint32_t conditional_intra_du_mob_info_ext_ies_o::idx_to_id(uint32_t idx)
{
  static const uint32_t names[] = {433, 786, 791};
  return map_enum_number(names, 3, idx, "id");
}
bool conditional_intra_du_mob_info_ext_ies_o::is_id_valid(const uint32_t& id)
{
  static const uint32_t names[] = {433, 786, 791};
  for (const auto& o : names) {
    if (o == id) {
      return true;
    }
  }
  return false;
}
crit_e conditional_intra_du_mob_info_ext_ies_o::get_crit(const uint32_t& id)
{
  switch (id) {
    case 433:
      return crit_e::ignore;
    case 786:
      return crit_e::reject;
    case 791:
      return crit_e::reject;
    default:
      asn1::log_error("The id={} is not recognized", id);
  }
  return {};
}
presence_e conditional_intra_du_mob_info_ext_ies_o::get_presence(const uint32_t& id)
{
  switch (id) {
    case 433:
      return presence_e::optional;
    case 786:
      return presence_e::optional;
    case 791:
      return presence_e::optional;
    default:
      asn1::log_error("The id={} is not recognized", id);
  }
  return {};
}

OCUDUASN_CODE conditional_intra_du_mob_info_ext_ies_container::pack(bit_ref& bref) const
{
  uint32_t nof_ies = 0;
  nof_ies += estimated_arrival_probability_present ? 1 : 0;
  nof_ies += s_cp_ac_request_present ? 1 : 0;
  nof_ies += s_cp_ac_lower_layer_ref_cfg_request_present ? 1 : 0;
  HANDLE_CODE(pack_length(bref, nof_ies, 1u, 65535u, true));

  if (estimated_arrival_probability_present) {
    HANDLE_CODE(pack_ie(bref, 433, crit_e{crit_e::ignore}, [this, &bref]() {
      return pack_integer(bref, estimated_arrival_probability, (uint8_t)1u, (uint8_t)100u, false, true);
    }));
  }
  if (s_cp_ac_request_present) {
    HANDLE_CODE(pack_ie(bref, 786, crit_e{crit_e::reject}, [this, &bref]() { return s_cp_ac_request.pack(bref); }));
  }
  if (s_cp_ac_lower_layer_ref_cfg_request_present) {
    HANDLE_CODE(pack_ie(
        bref, 791, crit_e{crit_e::reject}, [this, &bref]() { return s_cp_ac_lower_layer_ref_cfg_request.pack(bref); }));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE conditional_intra_du_mob_info_ext_ies_container::unpack(cbit_ref& bref)
{
  uint32_t nof_ies = 0;
  HANDLE_CODE(unpack_length(nof_ies, bref, 1u, 65535u, true));

  for (; nof_ies > 0; --nof_ies) {
    uint32_t id;
    crit_e   crit;
    HANDLE_CODE(unpack_ie_header(bref, id, crit, &conditional_intra_du_mob_info_ext_ies_o::get_crit));

    switch (id) {
      case 433: {
        estimated_arrival_probability_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() {
          return unpack_integer(estimated_arrival_probability, bref, (uint8_t)1u, (uint8_t)100u, false, true);
        }));
        break;
      }
      case 786: {
        s_cp_ac_request_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() { return s_cp_ac_request.unpack(bref); }));
        break;
      }
      case 791: {
        s_cp_ac_lower_layer_ref_cfg_request_present = true;
        HANDLE_CODE(
            unpack_ie_value(bref, [this, &bref]() { return s_cp_ac_lower_layer_ref_cfg_request.unpack(bref); }));
        break;
      }
      default:
        HANDLE_CODE(skip_ignored_ie(bref, crit, id));
        break;
    }
  }

  return OCUDUASN_SUCCESS;
}
void conditional_intra_du_mob_info_ext_ies_container::to_json(json_writer& j) const
{
  j.start_array();
  if (estimated_arrival_probability_present) {
    j.start_obj();
    j.write_int("id", 433);
    j.write_str("criticality", "ignore");
    j.write_int("extensionValue", estimated_arrival_probability);
    j.end_obj();
  }
  if (s_cp_ac_request_present) {
    j.start_obj();
    j.write_int("id", 786);
    j.write_str("criticality", "reject");
    j.write_str("extensionValue", "initiation");
    j.end_obj();
  }
  if (s_cp_ac_lower_layer_ref_cfg_request_present) {
    j.start_obj();
    j.write_int("id", 791);
    j.write_str("criticality", "reject");
    j.write_str("extensionValue", "true");
    j.end_obj();
  }
  j.end_array();
}

