crit_e time_stamp_ext_ies_o::get_crit(const uint32_t& id)
{
  if (id == 814) {
    return crit_e::ignore;
  }
  asn1::log_error("The id={} is not recognized", id);
  return {};
}
presence_e time_stamp_ext_ies_o::get_presence(const uint32_t& id)
{
  if (id == 814) {
    return presence_e::optional;
  }
  asn1::log_error("The id={} is not recognized", id);
  return {};
}

OCUDUASN_CODE time_stamp_ext_ies_container::pack(bit_ref& bref) const
{
  uint32_t nof_ies = 0;
  nof_ies += symbol_idx_present ? 1 : 0;
  HANDLE_CODE(pack_length(bref, nof_ies, 1u, 65535u, true));

  if (symbol_idx_present) {
    HANDLE_CODE(pack_ie(bref, 814, crit_e{crit_e::ignore}, [this, &bref]() {
      return pack_integer(bref, symbol_idx, (uint8_t)0u, (uint8_t)13u, false, true);
    }));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE time_stamp_ext_ies_container::unpack(cbit_ref& bref)
{
  uint32_t nof_ies = 0;
  HANDLE_CODE(unpack_length(nof_ies, bref, 1u, 65535u, true));

  for (; nof_ies > 0; --nof_ies) {
    uint32_t id;
    crit_e   crit;
    HANDLE_CODE(unpack_ie_header(bref, id, crit, &time_stamp_ext_ies_o::get_crit));

    if (id == 814) {
      {
        symbol_idx_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() {
          return unpack_integer(symbol_idx, bref, (uint8_t)0u, (uint8_t)13u, false, true);
        }));
      }
    } else {
      HANDLE_CODE(skip_ignored_ie(bref, crit, id));
    }
  }

  return OCUDUASN_SUCCESS;
}
void time_stamp_ext_ies_container::to_json(json_writer& j) const
{
  j.start_array();
  if (symbol_idx_present) {
    j.start_obj();
    j.write_int("id", 814);
    j.write_str("criticality", "ignore");
    j.write_int("extensionValue", symbol_idx);
    j.end_obj();
  }
  j.end_array();
}

