// E-CID-MeasurementResult-ExtIEs ::= OBJECT SET OF F1AP-PROTOCOL-EXTENSION
uint32_t e_c_id_meas_result_ext_ies_o::idx_to_id(uint32_t idx)
{
  static const uint32_t names[] = {766, 834};
  return map_enum_number(names, 2, idx, "id");
}
bool e_c_id_meas_result_ext_ies_o::is_id_valid(const uint32_t& id)
{
  static const uint32_t names[] = {766, 834};
  for (const auto& o : names) {
    if (o == id) {
      return true;
    }
  }
  return false;
}
crit_e e_c_id_meas_result_ext_ies_o::get_crit(const uint32_t& id)
{
  switch (id) {
    case 766:
      return crit_e::ignore;
    case 834:
      return crit_e::ignore;
    default:
      asn1::log_error("The id={} is not recognized", id);
  }
  return {};
}
presence_e e_c_id_meas_result_ext_ies_o::get_presence(const uint32_t& id)
{
  switch (id) {
    case 766:
      return presence_e::optional;
    case 834:
      return presence_e::optional;
    default:
      asn1::log_error("The id={} is not recognized", id);
  }
  return {};
}

OCUDUASN_CODE e_c_id_meas_result_ext_ies_container::pack(bit_ref& bref) const
{
  uint32_t nof_ies = 0;
  nof_ies += mobile_access_point_location_present ? 1 : 0;
  nof_ies += e_c_id_measured_results_associated_info_list_present ? 1 : 0;
  HANDLE_CODE(pack_length(bref, nof_ies, 1u, 65535u, true));

  if (mobile_access_point_location_present) {
    HANDLE_CODE(pack_ie(
        bref, 766, crit_e{crit_e::ignore}, [this, &bref]() { return mobile_access_point_location.pack(bref); }));
  }
  if (e_c_id_measured_results_associated_info_list_present) {
    HANDLE_CODE(pack_ie(bref, 834, crit_e{crit_e::ignore}, [this, &bref]() {
      return pack_dyn_seq_of(bref, e_c_id_measured_results_associated_info_list, 1, 64, true);
    }));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE e_c_id_meas_result_ext_ies_container::unpack(cbit_ref& bref)
{
  uint32_t nof_ies = 0;
  HANDLE_CODE(unpack_length(nof_ies, bref, 1u, 65535u, true));

  for (; nof_ies > 0; --nof_ies) {
    uint32_t id;
    crit_e   crit;
    HANDLE_CODE(unpack_ie_header(bref, id, crit, &e_c_id_meas_result_ext_ies_o::get_crit));

    switch (id) {
      case 766: {
        mobile_access_point_location_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() { return mobile_access_point_location.unpack(bref); }));
        break;
      }
      case 834: {
        e_c_id_measured_results_associated_info_list_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() {
          return unpack_dyn_seq_of(e_c_id_measured_results_associated_info_list, bref, 1, 64, true);
        }));
        break;
      }
      default:
        HANDLE_CODE(skip_ignored_ie(bref, crit, id));
        break;
    }
  }

  return OCUDUASN_SUCCESS;
}
void e_c_id_meas_result_ext_ies_container::to_json(json_writer& j) const
{
  j.start_array();
  if (mobile_access_point_location_present) {
    j.start_obj();
    j.write_int("id", 766);
    j.write_str("criticality", "ignore");
    j.write_fieldname("extensionValue");
    mobile_access_point_location.to_json(j);
    j.end_obj();
  }
  if (e_c_id_measured_results_associated_info_list_present) {
    j.start_obj();
    j.write_int("id", 834);
    j.write_str("criticality", "ignore");
    j.start_array("extensionValue");
    for (const auto& e1 : e_c_id_measured_results_associated_info_list) {
      e1.to_json(j);
    }
    j.end_array();
    j.end_obj();
  }
  j.end_array();
}

// E-CID-MeasurementResult ::= SEQUENCE
OCUDUASN_CODE e_c_id_meas_result_s::pack(bit_ref& bref) const
{
  HANDLE_CODE(bref.pack(geographical_coordinates_present, 1));
  HANDLE_CODE(bref.pack(measured_results_list.size() > 0, 1));
  HANDLE_CODE(bref.pack(ie_exts_present, 1));

  if (geographical_coordinates_present) {
    HANDLE_CODE(geographical_coordinates.pack(bref));
  }
  if (measured_results_list.size() > 0) {
    HANDLE_CODE(pack_dyn_seq_of(bref, measured_results_list, 1, 64, true));
  }
  if (ie_exts_present) {
    HANDLE_CODE(ie_exts.pack(bref));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE e_c_id_meas_result_s::unpack(cbit_ref& bref)
{
  HANDLE_CODE(bref.unpack(geographical_coordinates_present, 1));
  bool measured_results_list_present;
  HANDLE_CODE(bref.unpack(measured_results_list_present, 1));
  HANDLE_CODE(bref.unpack(ie_exts_present, 1));

  if (geographical_coordinates_present) {
    HANDLE_CODE(geographical_coordinates.unpack(bref));
  }
  if (measured_results_list_present) {
    HANDLE_CODE(unpack_dyn_seq_of(measured_results_list, bref, 1, 64, true));
  }
  if (ie_exts_present) {
    HANDLE_CODE(ie_exts.unpack(bref));
  }

  return OCUDUASN_SUCCESS;
}
void e_c_id_meas_result_s::to_json(json_writer& j) const
{
  j.start_obj();
  if (geographical_coordinates_present) {
    j.write_fieldname("geographicalCoordinates");
    geographical_coordinates.to_json(j);
  }
  if (measured_results_list.size() > 0) {
    j.start_array("measuredResults-List");
    for (const auto& e1 : measured_results_list) {
      e1.to_json(j);
    }
    j.end_array();
  }
  if (ie_exts_present) {
    j.write_fieldname("iE-Extensions");
    ie_exts.to_json(j);
  }
  j.end_obj();
}

