// NSAGSupportItem ::= SEQUENCE
OCUDUASN_CODE nsag_support_item_s::pack(bit_ref& bref) const
{
  bref.pack(false, 1);
  HANDLE_CODE(bref.pack(ie_exts_present, 1));

  HANDLE_CODE(pack_integer(bref, nsag_id, (uint16_t)0u, (uint16_t)255u, true, true));
  HANDLE_CODE(pack_dyn_seq_of(bref, nsag_slice_support, 1, 65535, true));
  if (ie_exts_present) {
    HANDLE_CODE(ie_exts.pack(bref));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE nsag_support_item_s::unpack(cbit_ref& bref)
{
  bool ext;
  HANDLE_CODE(bref.unpack(ext, 1));
  HANDLE_CODE(bref.unpack(ie_exts_present, 1));

  HANDLE_CODE(unpack_integer(nsag_id, bref, (uint16_t)0u, (uint16_t)255u, true, true));
  HANDLE_CODE(unpack_dyn_seq_of(nsag_slice_support, bref, 1, 65535, true));
  if (ie_exts_present) {
    HANDLE_CODE(ie_exts.unpack(bref));
  }

  if (ext) {
    ext_groups_unpacker unknown_ext_unpacker(bref, true);
    HANDLE_CODE(unknown_ext_unpacker.consume_remaining_groups(bref));
  }
  return OCUDUASN_SUCCESS;
}
void nsag_support_item_s::to_json(json_writer& j) const
{
  j.start_obj();
  j.write_int("nSAG-ID", nsag_id);
  j.start_array("nSAGSliceSupport");
  for (const auto& e1 : nsag_slice_support) {
    e1.to_json(j);
  }
  j.end_array();
  if (ie_exts_present) {
    j.write_fieldname("iE-Extensions");
    ie_exts.to_json(j);
  }
  j.end_obj();
}

// ExtendedServedPLMNs-ItemExtIEs ::= OBJECT SET OF F1AP-PROTOCOL-EXTENSION
uint32_t extended_served_plmns_item_ext_ies_o::idx_to_id(uint32_t idx)
{
  static const uint32_t names[] = {384, 390, 644};
  return map_enum_number(names, 3, idx, "id");
}
bool extended_served_plmns_item_ext_ies_o::is_id_valid(const uint32_t& id)
{
  static const uint32_t names[] = {384, 390, 644};
  for (const auto& o : names) {
    if (o == id) {
      return true;
    }
  }
  return false;
}
crit_e extended_served_plmns_item_ext_ies_o::get_crit(const uint32_t& id)
{
  switch (id) {
    case 384:
      return crit_e::reject;
    case 390:
      return crit_e::reject;
    case 644:
      return crit_e::ignore;
    default:
      asn1::log_error("The id={} is not recognized", id);
  }
  return {};
}
presence_e extended_served_plmns_item_ext_ies_o::get_presence(const uint32_t& id)
{
  switch (id) {
    case 384:
      return presence_e::optional;
    case 390:
      return presence_e::optional;
    case 644:
      return presence_e::optional;
    default:
      asn1::log_error("The id={} is not recognized", id);
  }
  return {};
}

OCUDUASN_CODE extended_served_plmns_item_ext_ies_container::pack(bit_ref& bref) const
{
  uint32_t nof_ies = 0;
  nof_ies += npn_support_info_present ? 1 : 0;
  nof_ies += extended_tai_slice_support_list_present ? 1 : 0;
  nof_ies += tai_nsag_support_list_present ? 1 : 0;
  HANDLE_CODE(pack_length(bref, nof_ies, 1u, 65535u, true));

  if (npn_support_info_present) {
    HANDLE_CODE(pack_ie(bref, 384, crit_e{crit_e::reject}, [this, &bref]() { return npn_support_info.pack(bref); }));
  }
  if (extended_tai_slice_support_list_present) {
    HANDLE_CODE(pack_ie(bref, 390, crit_e{crit_e::reject}, [this, &bref]() {
      return pack_dyn_seq_of(bref, extended_tai_slice_support_list, 1, 65535, true);
    }));
  }
  if (tai_nsag_support_list_present) {
    HANDLE_CODE(pack_ie(bref, 644, crit_e{crit_e::ignore}, [this, &bref]() {
      return pack_dyn_seq_of(bref, tai_nsag_support_list, 1, 256, true);
    }));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE extended_served_plmns_item_ext_ies_container::unpack(cbit_ref& bref)
{
  uint32_t nof_ies = 0;
  HANDLE_CODE(unpack_length(nof_ies, bref, 1u, 65535u, true));

  for (; nof_ies > 0; --nof_ies) {
    uint32_t id;
    crit_e   crit;
    HANDLE_CODE(unpack_ie_header(bref, id, crit, &extended_served_plmns_item_ext_ies_o::get_crit));

    switch (id) {
      case 384: {
        npn_support_info_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() { return npn_support_info.unpack(bref); }));
        break;
      }
      case 390: {
        extended_tai_slice_support_list_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() {
          return unpack_dyn_seq_of(extended_tai_slice_support_list, bref, 1, 65535, true);
        }));
        break;
      }
      case 644: {
        tai_nsag_support_list_present = true;
        HANDLE_CODE(unpack_ie_value(
            bref, [this, &bref]() { return unpack_dyn_seq_of(tai_nsag_support_list, bref, 1, 256, true); }));
        break;
      }
      default:
        HANDLE_CODE(skip_ignored_ie(bref, crit, id));
        break;
    }
  }

  return OCUDUASN_SUCCESS;
}
void extended_served_plmns_item_ext_ies_container::to_json(json_writer& j) const
{
  j.start_array();
  if (npn_support_info_present) {
    j.start_obj();
    j.write_int("id", 384);
    j.write_str("criticality", "reject");
    j.write_fieldname("extensionValue");
    npn_support_info.to_json(j);
    j.end_obj();
  }
  if (extended_tai_slice_support_list_present) {
    j.start_obj();
    j.write_int("id", 390);
    j.write_str("criticality", "reject");
    j.start_array("extensionValue");
    for (const auto& e1 : extended_tai_slice_support_list) {
      e1.to_json(j);
    }
    j.end_array();
    j.end_obj();
  }
  if (tai_nsag_support_list_present) {
    j.start_obj();
    j.write_int("id", 644);
    j.write_str("criticality", "ignore");
    j.start_array("extensionValue");
    for (const auto& e1 : tai_nsag_support_list) {
      e1.to_json(j);
    }
    j.end_array();
    j.end_obj();
  }
  j.end_array();
}

// ExtendedServedPLMNs-Item ::= SEQUENCE
OCUDUASN_CODE extended_served_plmns_item_s::pack(bit_ref& bref) const
{
  bref.pack(false, 1);
  HANDLE_CODE(bref.pack(tai_slice_support_list.size() > 0, 1));
  HANDLE_CODE(bref.pack(ie_exts_present, 1));

  HANDLE_CODE(plmn_id.pack(bref));
  if (tai_slice_support_list.size() > 0) {
    HANDLE_CODE(pack_dyn_seq_of(bref, tai_slice_support_list, 1, 1024, true));
  }
  if (ie_exts_present) {
    HANDLE_CODE(ie_exts.pack(bref));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE extended_served_plmns_item_s::unpack(cbit_ref& bref)
{
  bool ext;
  HANDLE_CODE(bref.unpack(ext, 1));
  bool tai_slice_support_list_present;
  HANDLE_CODE(bref.unpack(tai_slice_support_list_present, 1));
  HANDLE_CODE(bref.unpack(ie_exts_present, 1));

  HANDLE_CODE(plmn_id.unpack(bref));
  if (tai_slice_support_list_present) {
    HANDLE_CODE(unpack_dyn_seq_of(tai_slice_support_list, bref, 1, 1024, true));
  }
  if (ie_exts_present) {
    HANDLE_CODE(ie_exts.unpack(bref));
  }

  if (ext) {
    ext_groups_unpacker unknown_ext_unpacker(bref, true);
    HANDLE_CODE(unknown_ext_unpacker.consume_remaining_groups(bref));
  }
  return OCUDUASN_SUCCESS;
}
void extended_served_plmns_item_s::to_json(json_writer& j) const
{
  j.start_obj();
  j.write_str("pLMN-Identity", plmn_id.to_string());
  if (tai_slice_support_list.size() > 0) {
    j.start_array("tAISliceSupportList");
    for (const auto& e1 : tai_slice_support_list) {
      e1.to_json(j);
    }
    j.end_array();
  }
  if (ie_exts_present) {
    j.write_fieldname("iE-Extensions");
    ie_exts.to_json(j);
  }
  j.end_obj();
}

