// ServedPLMNs-ItemExtIEs ::= OBJECT SET OF F1AP-PROTOCOL-EXTENSION
uint32_t served_plmns_item_ext_ies_o::idx_to_id(uint32_t idx)
{
  static const uint32_t names[] = {131, 384, 390, 644};
  return map_enum_number(names, 4, idx, "id");
}
bool served_plmns_item_ext_ies_o::is_id_valid(const uint32_t& id)
{
  static const uint32_t names[] = {131, 384, 390, 644};
  for (const auto& o : names) {
    if (o == id) {
      return true;
    }
  }
  return false;
}
crit_e served_plmns_item_ext_ies_o::get_crit(const uint32_t& id)
{
  switch (id) {
    case 131:
      return crit_e::ignore;
    case 384:
      return crit_e::reject;
    case 390:
      return crit_e::reject;
    case 644:
      return crit_e::ignore;
    default:
      asn1::log_error("The id={} is not recognized", id);
  }
  return {};
}
presence_e served_plmns_item_ext_ies_o::get_presence(const uint32_t& id)
{
  switch (id) {
    case 131:
      return presence_e::optional;
    case 384:
      return presence_e::optional;
    case 390:
      return presence_e::optional;
    case 644:
      return presence_e::optional;
    default:
      asn1::log_error("The id={} is not recognized", id);
  }
  return {};
}

OCUDUASN_CODE served_plmns_item_ext_ies_container::pack(bit_ref& bref) const
{
  uint32_t nof_ies = 0;
  nof_ies += tai_slice_support_list_present ? 1 : 0;
  nof_ies += npn_support_info_present ? 1 : 0;
  nof_ies += extended_tai_slice_support_list_present ? 1 : 0;
  nof_ies += tai_nsag_support_list_present ? 1 : 0;
  HANDLE_CODE(pack_length(bref, nof_ies, 1u, 65535u, true));

  if (tai_slice_support_list_present) {
    HANDLE_CODE(pack_ie(bref, 131, crit_e{crit_e::ignore}, [this, &bref]() {
      return pack_dyn_seq_of(bref, tai_slice_support_list, 1, 1024, true);
    }));
  }
  if (npn_support_info_present) {
    HANDLE_CODE(pack_ie(bref, 384, crit_e{crit_e::reject}, [this, &bref]() { return npn_support_info.pack(bref); }));
  }
  if (extended_tai_slice_support_list_present) {
    HANDLE_CODE(pack_ie(bref, 390, crit_e{crit_e::reject}, [this, &bref]() {
      return pack_dyn_seq_of(bref, extended_tai_slice_support_list, 1, 65535, true);
    }));
  }
  if (tai_nsag_support_list_present) {
    HANDLE_CODE(pack_ie(bref, 644, crit_e{crit_e::ignore}, [this, &bref]() {
      return pack_dyn_seq_of(bref, tai_nsag_support_list, 1, 256, true);
    }));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE served_plmns_item_ext_ies_container::unpack(cbit_ref& bref)
{
  uint32_t nof_ies = 0;
  HANDLE_CODE(unpack_length(nof_ies, bref, 1u, 65535u, true));

  for (; nof_ies > 0; --nof_ies) {
    uint32_t id;
    crit_e   crit;
    HANDLE_CODE(unpack_ie_header(bref, id, crit, &served_plmns_item_ext_ies_o::get_crit));

    switch (id) {
      case 131: {
        tai_slice_support_list_present = true;
        HANDLE_CODE(unpack_ie_value(
            bref, [this, &bref]() { return unpack_dyn_seq_of(tai_slice_support_list, bref, 1, 1024, true); }));
        break;
      }
      case 384: {
        npn_support_info_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() { return npn_support_info.unpack(bref); }));
        break;
      }
      case 390: {
        extended_tai_slice_support_list_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() {
          return unpack_dyn_seq_of(extended_tai_slice_support_list, bref, 1, 65535, true);
        }));
        break;
      }
      case 644: {
        tai_nsag_support_list_present = true;
        HANDLE_CODE(unpack_ie_value(
            bref, [this, &bref]() { return unpack_dyn_seq_of(tai_nsag_support_list, bref, 1, 256, true); }));
        break;
      }
      default:
        HANDLE_CODE(skip_ignored_ie(bref, crit, id));
        break;
    }
  }

  return OCUDUASN_SUCCESS;
}
void served_plmns_item_ext_ies_container::to_json(json_writer& j) const
{
  j.start_array();
  if (tai_slice_support_list_present) {
    j.start_obj();
    j.write_int("id", 131);
    j.write_str("criticality", "ignore");
    j.start_array("extensionValue");
    for (const auto& e1 : tai_slice_support_list) {
      e1.to_json(j);
    }
    j.end_array();
    j.end_obj();
  }
  if (npn_support_info_present) {
    j.start_obj();
    j.write_int("id", 384);
    j.write_str("criticality", "reject");
    j.write_fieldname("extensionValue");
    npn_support_info.to_json(j);
    j.end_obj();
  }
  if (extended_tai_slice_support_list_present) {
    j.start_obj();
    j.write_int("id", 390);
    j.write_str("criticality", "reject");
    j.start_array("extensionValue");
    for (const auto& e1 : extended_tai_slice_support_list) {
      e1.to_json(j);
    }
    j.end_array();
    j.end_obj();
  }
  if (tai_nsag_support_list_present) {
    j.start_obj();
    j.write_int("id", 644);
    j.write_str("criticality", "ignore");
    j.start_array("extensionValue");
    for (const auto& e1 : tai_nsag_support_list) {
      e1.to_json(j);
    }
    j.end_array();
    j.end_obj();
  }
  j.end_array();
}

// ServedPLMNs-Item ::= SEQUENCE
OCUDUASN_CODE served_plmns_item_s::pack(bit_ref& bref) const
{
  bref.pack(false, 1);
  HANDLE_CODE(bref.pack(ie_exts_present, 1));

  HANDLE_CODE(plmn_id.pack(bref));
  if (ie_exts_present) {
    HANDLE_CODE(ie_exts.pack(bref));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE served_plmns_item_s::unpack(cbit_ref& bref)
{
  bool ext;
  HANDLE_CODE(bref.unpack(ext, 1));
  HANDLE_CODE(bref.unpack(ie_exts_present, 1));

  HANDLE_CODE(plmn_id.unpack(bref));
  if (ie_exts_present) {
    HANDLE_CODE(ie_exts.unpack(bref));
  }

  if (ext) {
    ext_groups_unpacker unknown_ext_unpacker(bref, true);
    HANDLE_CODE(unknown_ext_unpacker.consume_remaining_groups(bref));
  }
  return OCUDUASN_SUCCESS;
}
void served_plmns_item_s::to_json(json_writer& j) const
{
  j.start_obj();
  j.write_str("pLMN-Identity", plmn_id.to_string());
  if (ie_exts_present) {
    j.write_fieldname("iE-Extensions");
    ie_exts.to_json(j);
  }
  j.end_obj();
}

