OCUDUASN_CODE ul_rtoa_meas_ext_ies_container::pack(bit_ref& bref) const
{
  uint32_t nof_ies = 0;
  nof_ies += extended_add_path_list_present ? 1 : 0;
  nof_ies += trp_rx_teg_info_present ? 1 : 0;
  HANDLE_CODE(pack_length(bref, nof_ies, 1u, 65535u, true));

  if (extended_add_path_list_present) {
    HANDLE_CODE(pack_ie(bref, 561, crit_e{crit_e::ignore}, [this, &bref]() {
      return pack_dyn_seq_of(bref, extended_add_path_list, 1, 8, true);
    }));
  }
  if (trp_rx_teg_info_present) {
    HANDLE_CODE(pack_ie(bref, 568, crit_e{crit_e::ignore}, [this, &bref]() { return trp_rx_teg_info.pack(bref); }));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE ul_rtoa_meas_ext_ies_container::unpack(cbit_ref& bref)
{
  uint32_t nof_ies = 0;
  HANDLE_CODE(unpack_length(nof_ies, bref, 1u, 65535u, true));

  for (; nof_ies > 0; --nof_ies) {
    uint32_t id;
    crit_e   crit;
    HANDLE_CODE(unpack_ie_header(bref, id, crit, &ul_rtoa_meas_ext_ies_o::get_crit));

    switch (id) {
      case 561: {
        extended_add_path_list_present = true;
        HANDLE_CODE(unpack_ie_value(
            bref, [this, &bref]() { return unpack_dyn_seq_of(extended_add_path_list, bref, 1, 8, true); }));
        break;
      }
      case 568: {
        trp_rx_teg_info_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() { return trp_rx_teg_info.unpack(bref); }));
        break;
      }
      default:
        HANDLE_CODE(skip_ignored_ie(bref, crit, id));
        break;
    }
  }

  return OCUDUASN_SUCCESS;
}
void ul_rtoa_meas_ext_ies_container::to_json(json_writer& j) const
{
  j.start_array();
  if (extended_add_path_list_present) {
    j.start_obj();
    j.write_int("id", 561);
    j.write_str("criticality", "ignore");
    j.start_array("extensionValue");
    for (const auto& e1 : extended_add_path_list) {
      e1.to_json(j);
    }
    j.end_array();
    j.end_obj();
  }
  if (trp_rx_teg_info_present) {
    j.start_obj();
    j.write_int("id", 568);
    j.write_str("criticality", "ignore");
    j.write_fieldname("extensionValue");
    trp_rx_teg_info.to_json(j);
    j.end_obj();
  }
  j.end_array();
}

// UL-RTOA-Measurement ::= SEQUENCE
OCUDUASN_CODE ul_rtoa_meas_s::pack(bit_ref& bref) const
{
  HANDLE_CODE(bref.pack(add_path_list.size() > 0, 1));
  HANDLE_CODE(bref.pack(ie_exts_present, 1));

  HANDLE_CODE(ul_rtoa_meas_item.pack(bref));
  if (add_path_list.size() > 0) {
    HANDLE_CODE(pack_dyn_seq_of(bref, add_path_list, 1, 2, true));
  }
  if (ie_exts_present) {
    HANDLE_CODE(ie_exts.pack(bref));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE ul_rtoa_meas_s::unpack(cbit_ref& bref)
{
  bool add_path_list_present;
  HANDLE_CODE(bref.unpack(add_path_list_present, 1));
  HANDLE_CODE(bref.unpack(ie_exts_present, 1));

  HANDLE_CODE(ul_rtoa_meas_item.unpack(bref));
  if (add_path_list_present) {
    HANDLE_CODE(unpack_dyn_seq_of(add_path_list, bref, 1, 2, true));
  }
  if (ie_exts_present) {
    HANDLE_CODE(ie_exts.unpack(bref));
  }

  return OCUDUASN_SUCCESS;
}
void ul_rtoa_meas_s::to_json(json_writer& j) const
{
  j.start_obj();
  j.write_fieldname("uL-RTOA-MeasurementItem");
  ul_rtoa_meas_item.to_json(j);
  if (add_path_list.size() > 0) {
    j.start_array("additionalPath-List");
    for (const auto& e1 : add_path_list) {
      e1.to_json(j);
    }
    j.end_array();
  }
  if (ie_exts_present) {
    j.write_fieldname("iE-Extensions");
    ie_exts.to_json(j);
  }
  j.end_obj();
}

// UL-RSCP ::= SEQUENCE
OCUDUASN_CODE ul_rs_cp_s::pack(bit_ref& bref) const
{
  bref.pack(false, 1);
  HANDLE_CODE(bref.pack(ie_exts_present, 1));

  HANDLE_CODE(pack_integer(bref, ul_rs_cp, (uint16_t)0u, (uint16_t)3599u, false, true));
  if (ie_exts_present) {
    HANDLE_CODE(ie_exts.pack(bref));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE ul_rs_cp_s::unpack(cbit_ref& bref)
{
  bool ext;
  HANDLE_CODE(bref.unpack(ext, 1));
  HANDLE_CODE(bref.unpack(ie_exts_present, 1));

  HANDLE_CODE(unpack_integer(ul_rs_cp, bref, (uint16_t)0u, (uint16_t)3599u, false, true));
  if (ie_exts_present) {
    HANDLE_CODE(ie_exts.unpack(bref));
  }

  if (ext) {
    ext_groups_unpacker unknown_ext_unpacker(bref, true);
    HANDLE_CODE(unknown_ext_unpacker.consume_remaining_groups(bref));
  }
  return OCUDUASN_SUCCESS;
}
void ul_rs_cp_s::to_json(json_writer& j) const
{
  j.start_obj();
  j.write_int("uLRSCP", ul_rs_cp);
  if (ie_exts_present) {
    j.write_fieldname("iE-extensions");
    ie_exts.to_json(j);
  }
  j.end_obj();
}

