// PRSAngleItem-ItemExtIEs ::= OBJECT SET OF F1AP-PROTOCOL-EXTENSION
uint32_t prs_angle_item_item_ext_ies_o::idx_to_id(uint32_t idx)
{
  static const uint32_t names[] = {439};
  return map_enum_number(names, 1, idx, "id");
}
bool prs_angle_item_item_ext_ies_o::is_id_valid(const uint32_t& id)
{
  return 439 == id;
}
crit_e prs_angle_item_item_ext_ies_o::get_crit(const uint32_t& id)
{
  if (id == 439) {
    return crit_e::ignore;
  }
  asn1::log_error("The id={} is not recognized", id);
  return {};
}
presence_e prs_angle_item_item_ext_ies_o::get_presence(const uint32_t& id)
{
  if (id == 439) {
    return presence_e::optional;
  }
  asn1::log_error("The id={} is not recognized", id);
  return {};
}

OCUDUASN_CODE prs_angle_item_item_ext_ies_container::pack(bit_ref& bref) const
{
  uint32_t nof_ies = 0;
  nof_ies += prs_res_id_present ? 1 : 0;
  HANDLE_CODE(pack_length(bref, nof_ies, 1u, 65535u, true));

  if (prs_res_id_present) {
    HANDLE_CODE(pack_ie(bref, 439, crit_e{crit_e::ignore}, [this, &bref]() {
      return pack_integer(bref, prs_res_id, (uint8_t)0u, (uint8_t)63u, false, true);
    }));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE prs_angle_item_item_ext_ies_container::unpack(cbit_ref& bref)
{
  uint32_t nof_ies = 0;
  HANDLE_CODE(unpack_length(nof_ies, bref, 1u, 65535u, true));

  for (; nof_ies > 0; --nof_ies) {
    uint32_t id;
    crit_e   crit;
    HANDLE_CODE(unpack_ie_header(bref, id, crit, &prs_angle_item_item_ext_ies_o::get_crit));

    if (id == 439) {
      {
        prs_res_id_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() {
          return unpack_integer(prs_res_id, bref, (uint8_t)0u, (uint8_t)63u, false, true);
        }));
      }
    } else {
      HANDLE_CODE(skip_ignored_ie(bref, crit, id));
    }
  }

  return OCUDUASN_SUCCESS;
}
void prs_angle_item_item_ext_ies_container::to_json(json_writer& j) const
{
  j.start_array();
  if (prs_res_id_present) {
    j.start_obj();
    j.write_int("id", 439);
    j.write_str("criticality", "ignore");
    j.write_int("extensionValue", prs_res_id);
    j.end_obj();
  }
  j.end_array();
}

