// PRSConfiguration-ExtIEs ::= OBJECT SET OF F1AP-PROTOCOL-EXTENSION
uint32_t prs_cfg_ext_ies_o::idx_to_id(uint32_t idx)
{
  static const uint32_t names[] = {817};
  return map_enum_number(names, 1, idx, "id");
}
bool prs_cfg_ext_ies_o::is_id_valid(const uint32_t& id)
{
  return 817 == id;
}
crit_e prs_cfg_ext_ies_o::get_crit(const uint32_t& id)
{
  if (id == 817) {
    return crit_e::ignore;
  }
  asn1::log_error("The id={} is not recognized", id);
  return {};
}
presence_e prs_cfg_ext_ies_o::get_presence(const uint32_t& id)
{
  if (id == 817) {
    return presence_e::optional;
  }
  asn1::log_error("The id={} is not recognized", id);
  return {};
}

OCUDUASN_CODE prs_cfg_ext_ies_container::pack(bit_ref& bref) const
{
  uint32_t nof_ies = 0;
  nof_ies += aggr_prs_res_set_list_present ? 1 : 0;
  HANDLE_CODE(pack_length(bref, nof_ies, 1u, 65535u, true));

  if (aggr_prs_res_set_list_present) {
    HANDLE_CODE(pack_ie(bref, 817, crit_e{crit_e::ignore}, [this, &bref]() {
      return pack_dyn_seq_of(bref, aggr_prs_res_set_list, 1, 2, true);
    }));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE prs_cfg_ext_ies_container::unpack(cbit_ref& bref)
{
  uint32_t nof_ies = 0;
  HANDLE_CODE(unpack_length(nof_ies, bref, 1u, 65535u, true));

  for (; nof_ies > 0; --nof_ies) {
    uint32_t id;
    crit_e   crit;
    HANDLE_CODE(unpack_ie_header(bref, id, crit, &prs_cfg_ext_ies_o::get_crit));

    if (id == 817) {
      {
        aggr_prs_res_set_list_present = true;
        HANDLE_CODE(unpack_ie_value(
            bref, [this, &bref]() { return unpack_dyn_seq_of(aggr_prs_res_set_list, bref, 1, 2, true); }));
      }
    } else {
      HANDLE_CODE(skip_ignored_ie(bref, crit, id));
    }
  }

  return OCUDUASN_SUCCESS;
}
void prs_cfg_ext_ies_container::to_json(json_writer& j) const
{
  j.start_array();
  if (aggr_prs_res_set_list_present) {
    j.start_obj();
    j.write_int("id", 817);
    j.write_str("criticality", "ignore");
    j.start_array("extensionValue");
    for (const auto& e1 : aggr_prs_res_set_list) {
      e1.to_json(j);
    }
    j.end_array();
    j.end_obj();
  }
  j.end_array();
}

// PRSConfiguration ::= SEQUENCE
OCUDUASN_CODE prs_cfg_s::pack(bit_ref& bref) const
{
  HANDLE_CODE(bref.pack(ie_exts_present, 1));

  HANDLE_CODE(pack_dyn_seq_of(bref, prs_res_set_list, 1, 8, true));
  if (ie_exts_present) {
    HANDLE_CODE(ie_exts.pack(bref));
  }

  return OCUDUASN_SUCCESS;
}
