// PWSSystemInformationExtIEs ::= OBJECT SET OF F1AP-PROTOCOL-EXTENSION
uint32_t pws_sys_info_ext_ies_o::idx_to_id(uint32_t idx)
{
  static const uint32_t names[] = {220, 231};
  return map_enum_number(names, 2, idx, "id");
}
bool pws_sys_info_ext_ies_o::is_id_valid(const uint32_t& id)
{
  static const uint32_t names[] = {220, 231};
  for (const auto& o : names) {
    if (o == id) {
      return true;
    }
  }
  return false;
}
crit_e pws_sys_info_ext_ies_o::get_crit(const uint32_t& id)
{
  switch (id) {
    case 220:
      return crit_e::ignore;
    case 231:
      return crit_e::reject;
    default:
      asn1::log_error("The id={} is not recognized", id);
  }
  return {};
}
presence_e pws_sys_info_ext_ies_o::get_presence(const uint32_t& id)
{
  switch (id) {
    case 220:
      return presence_e::optional;
    case 231:
      return presence_e::optional;
    default:
      asn1::log_error("The id={} is not recognized", id);
  }
  return {};
}

OCUDUASN_CODE pws_sys_info_ext_ies_container::pack(bit_ref& bref) const
{
  uint32_t nof_ies = 0;
  nof_ies += notif_info_present ? 1 : 0;
  nof_ies += add_sib_msg_list_present ? 1 : 0;
  HANDLE_CODE(pack_length(bref, nof_ies, 1u, 65535u, true));

  if (notif_info_present) {
    HANDLE_CODE(pack_ie(bref, 220, crit_e{crit_e::ignore}, [this, &bref]() { return notif_info.pack(bref); }));
  }
  if (add_sib_msg_list_present) {
    HANDLE_CODE(pack_ie(bref, 231, crit_e{crit_e::reject}, [this, &bref]() {
      return pack_dyn_seq_of(bref, add_sib_msg_list, 1, 63, true);
    }));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE pws_sys_info_ext_ies_container::unpack(cbit_ref& bref)
{
  uint32_t nof_ies = 0;
  HANDLE_CODE(unpack_length(nof_ies, bref, 1u, 65535u, true));

  for (; nof_ies > 0; --nof_ies) {
    uint32_t id;
    crit_e   crit;
    HANDLE_CODE(unpack_ie_header(bref, id, crit, &pws_sys_info_ext_ies_o::get_crit));

    switch (id) {
      case 220: {
        notif_info_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() { return notif_info.unpack(bref); }));
        break;
      }
      case 231: {
        add_sib_msg_list_present = true;
        HANDLE_CODE(
            unpack_ie_value(bref, [this, &bref]() { return unpack_dyn_seq_of(add_sib_msg_list, bref, 1, 63, true); }));
        break;
      }
      default:
        HANDLE_CODE(skip_ignored_ie(bref, crit, id));
        break;
    }
  }

  return OCUDUASN_SUCCESS;
}
void pws_sys_info_ext_ies_container::to_json(json_writer& j) const
{
  j.start_array();
  if (notif_info_present) {
    j.start_obj();
    j.write_int("id", 220);
    j.write_str("criticality", "ignore");
    j.write_fieldname("extensionValue");
    notif_info.to_json(j);
    j.end_obj();
  }
  if (add_sib_msg_list_present) {
    j.start_obj();
    j.write_int("id", 231);
    j.write_str("criticality", "reject");
    j.start_array("extensionValue");
    for (const auto& e1 : add_sib_msg_list) {
      e1.to_json(j);
    }
    j.end_array();
    j.end_obj();
  }
  j.end_array();
}

