bool pos_meas_result_item_ext_ies_o::is_id_valid(const uint32_t& id)
{
  static const uint32_t names[] = {557, 560, 562, 753, 816, 819, 847};
  for (const auto& o : names) {
    if (o == id) {
      return true;
    }
  }
  return false;
}
