OCUDUASN_CODE pos_meas_result_list_item_ext_ies_container::pack(bit_ref& bref) const
{
  uint32_t nof_ies = 0;
  nof_ies += nr_cgi_present ? 1 : 0;
  HANDLE_CODE(pack_length(bref, nof_ies, 1u, 65535u, true));

  if (nr_cgi_present) {
    HANDLE_CODE(pack_ie(bref, 111, crit_e{crit_e::ignore}, [this, &bref]() { return nr_cgi.pack(bref); }));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE pos_meas_result_list_item_ext_ies_container::unpack(cbit_ref& bref)
{
  uint32_t nof_ies = 0;
  HANDLE_CODE(unpack_length(nof_ies, bref, 1u, 65535u, true));

  for (; nof_ies > 0; --nof_ies) {
    uint32_t id;
    crit_e   crit;
    HANDLE_CODE(unpack_ie_header(bref, id, crit, &pos_meas_result_list_item_ext_ies_o::get_crit));

    if (id == 111) {
      {
        nr_cgi_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() { return nr_cgi.unpack(bref); }));
      }
    } else {
      HANDLE_CODE(skip_ignored_ie(bref, crit, id));
    }
  }

  return OCUDUASN_SUCCESS;
}
void pos_meas_result_list_item_ext_ies_container::to_json(json_writer& j) const
{
  j.start_array();
  if (nr_cgi_present) {
    j.start_obj();
    j.write_int("id", 111);
    j.write_str("criticality", "ignore");
    j.write_fieldname("extensionValue");
    nr_cgi.to_json(j);
    j.end_obj();
  }
  j.end_array();
}

