// QoEInformationList-Item-ExtIEs ::= OBJECT SET OF F1AP-PROTOCOL-EXTENSION
uint32_t qo_e_info_list_item_ext_ies_o::idx_to_id(uint32_t idx)
{
  static const uint32_t names[] = {732};
  return map_enum_number(names, 1, idx, "id");
}
bool qo_e_info_list_item_ext_ies_o::is_id_valid(const uint32_t& id)
{
  return 732 == id;
}
crit_e qo_e_info_list_item_ext_ies_o::get_crit(const uint32_t& id)
{
  if (id == 732) {
    return crit_e::ignore;
  }
  asn1::log_error("The id={} is not recognized", id);
  return {};
}
presence_e qo_e_info_list_item_ext_ies_o::get_presence(const uint32_t& id)
{
  if (id == 732) {
    return presence_e::optional;
  }
  asn1::log_error("The id={} is not recognized", id);
  return {};
}

OCUDUASN_CODE qo_e_info_list_item_ext_ies_container::pack(bit_ref& bref) const
{
  uint32_t nof_ies = 0;
  nof_ies += drb_list_present ? 1 : 0;
  HANDLE_CODE(pack_length(bref, nof_ies, 1u, 65535u, true));

  if (drb_list_present) {
    HANDLE_CODE(pack_ie(
        bref, 732, crit_e{crit_e::ignore}, [this, &bref]() { return pack_dyn_seq_of(bref, drb_list, 1, 64, true); }));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE qo_e_info_list_item_ext_ies_container::unpack(cbit_ref& bref)
{
  uint32_t nof_ies = 0;
  HANDLE_CODE(unpack_length(nof_ies, bref, 1u, 65535u, true));

  for (; nof_ies > 0; --nof_ies) {
    uint32_t id;
    crit_e   crit;
    HANDLE_CODE(unpack_ie_header(bref, id, crit, &qo_e_info_list_item_ext_ies_o::get_crit));

    if (id == 732) {
      {
        drb_list_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() { return unpack_dyn_seq_of(drb_list, bref, 1, 64, true); }));
      }
    } else {
      HANDLE_CODE(skip_ignored_ie(bref, crit, id));
    }
  }

  return OCUDUASN_SUCCESS;
}
void qo_e_info_list_item_ext_ies_container::to_json(json_writer& j) const
{
  j.start_array();
  if (drb_list_present) {
    j.start_obj();
    j.write_int("id", 732);
    j.write_str("criticality", "ignore");
    j.start_array("extensionValue");
    for (const auto& e1 : drb_list) {
      e1.to_json(j);
    }
    j.end_array();
    j.end_obj();
  }
  j.end_array();
}

