// RRC-Version-ExtIEs ::= OBJECT SET OF F1AP-PROTOCOL-EXTENSION
uint32_t rrc_version_ext_ies_o::idx_to_id(uint32_t idx)
{
  static const uint32_t names[] = {199};
  return map_enum_number(names, 1, idx, "id");
}
bool rrc_version_ext_ies_o::is_id_valid(const uint32_t& id)
{
  return 199 == id;
}
crit_e rrc_version_ext_ies_o::get_crit(const uint32_t& id)
{
  if (id == 199) {
    return crit_e::ignore;
  }
  asn1::log_error("The id={} is not recognized", id);
  return {};
}
presence_e rrc_version_ext_ies_o::get_presence(const uint32_t& id)
{
  if (id == 199) {
    return presence_e::optional;
  }
  asn1::log_error("The id={} is not recognized", id);
  return {};
}

OCUDUASN_CODE rrc_version_ext_ies_container::pack(bit_ref& bref) const
{
  uint32_t nof_ies = 0;
  nof_ies += latest_rrc_version_enhanced_present ? 1 : 0;
  HANDLE_CODE(pack_length(bref, nof_ies, 1u, 65535u, true));

  if (latest_rrc_version_enhanced_present) {
    HANDLE_CODE(
        pack_ie(bref, 199, crit_e{crit_e::ignore}, [this, &bref]() { return latest_rrc_version_enhanced.pack(bref); }));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE rrc_version_ext_ies_container::unpack(cbit_ref& bref)
{
  uint32_t nof_ies = 0;
  HANDLE_CODE(unpack_length(nof_ies, bref, 1u, 65535u, true));

  for (; nof_ies > 0; --nof_ies) {
    uint32_t id;
    crit_e   crit;
    HANDLE_CODE(unpack_ie_header(bref, id, crit, &rrc_version_ext_ies_o::get_crit));

    if (id == 199) {
      {
        latest_rrc_version_enhanced_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() { return latest_rrc_version_enhanced.unpack(bref); }));
      }
    } else {
      HANDLE_CODE(skip_ignored_ie(bref, crit, id));
    }
  }

  return OCUDUASN_SUCCESS;
}
void rrc_version_ext_ies_container::to_json(json_writer& j) const
{
  j.start_array();
  if (latest_rrc_version_enhanced_present) {
    j.start_obj();
    j.write_int("id", 199);
    j.write_str("criticality", "ignore");
    j.write_str("extensionValue", latest_rrc_version_enhanced.to_string());
    j.end_obj();
  }
  j.end_array();
}

