bool srbs_to_be_setup_mod_item_ext_ies_o::is_id_valid(const uint32_t& id)
{
  static const uint32_t names[] = {372, 597, 589};
  for (const auto& o : names) {
    if (o == id) {
      return true;
    }
  }
  return false;
}
crit_e srbs_to_be_setup_mod_item_ext_ies_o::get_crit(const uint32_t& id)
{
  switch (id) {
    case 372:
      return crit_e::ignore;
    case 597:
      return crit_e::ignore;
    case 589:
      return crit_e::reject;
    default:
      asn1::log_error("The id={} is not recognized", id);
  }
  return {};
}
presence_e srbs_to_be_setup_mod_item_ext_ies_o::get_presence(const uint32_t& id)
{
  switch (id) {
    case 372:
      return presence_e::optional;
    case 597:
      return presence_e::optional;
    case 589:
      return presence_e::optional;
    default:
      asn1::log_error("The id={} is not recognized", id);
  }
  return {};
}

OCUDUASN_CODE srbs_to_be_setup_mod_item_ext_ies_container::pack(bit_ref& bref) const
{
  uint32_t nof_ies = 0;
  nof_ies += add_dupl_ind_present ? 1 : 0;
  nof_ies += srb_map_info_present ? 1 : 0;
  nof_ies += cg_sd_tind_setup_present ? 1 : 0;
  HANDLE_CODE(pack_length(bref, nof_ies, 1u, 65535u, true));

  if (add_dupl_ind_present) {
    HANDLE_CODE(pack_ie(bref, 372, crit_e{crit_e::ignore}, [this, &bref]() { return add_dupl_ind.pack(bref); }));
  }
  if (srb_map_info_present) {
    HANDLE_CODE(pack_ie(bref, 597, crit_e{crit_e::ignore}, [this, &bref]() {
      return pack_integer(bref, srb_map_info, (uint8_t)1u, (uint8_t)32u, false, true);
    }));
  }
  if (cg_sd_tind_setup_present) {
    HANDLE_CODE(pack_ie(bref, 589, crit_e{crit_e::reject}, [this, &bref]() { return cg_sd_tind_setup.pack(bref); }));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE srbs_to_be_setup_mod_item_ext_ies_container::unpack(cbit_ref& bref)
{
  uint32_t nof_ies = 0;
  HANDLE_CODE(unpack_length(nof_ies, bref, 1u, 65535u, true));

  for (; nof_ies > 0; --nof_ies) {
    uint32_t id;
    crit_e   crit;
    HANDLE_CODE(unpack_ie_header(bref, id, crit, &srbs_to_be_setup_mod_item_ext_ies_o::get_crit));

    switch (id) {
      case 372: {
        add_dupl_ind_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() { return add_dupl_ind.unpack(bref); }));
        break;
      }
      case 597: {
        srb_map_info_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() {
          return unpack_integer(srb_map_info, bref, (uint8_t)1u, (uint8_t)32u, false, true);
        }));
        break;
      }
      case 589: {
        cg_sd_tind_setup_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() { return cg_sd_tind_setup.unpack(bref); }));
        break;
      }
      default:
        HANDLE_CODE(skip_ignored_ie(bref, crit, id));
        break;
    }
  }

  return OCUDUASN_SUCCESS;
}
void srbs_to_be_setup_mod_item_ext_ies_container::to_json(json_writer& j) const
{
  j.start_array();
  if (add_dupl_ind_present) {
    j.start_obj();
    j.write_int("id", 372);
    j.write_str("criticality", "ignore");
    j.write_str("extensionValue", add_dupl_ind.to_string());
    j.end_obj();
  }
  if (srb_map_info_present) {
    j.start_obj();
    j.write_int("id", 597);
    j.write_str("criticality", "ignore");
    j.write_int("extensionValue", srb_map_info);
    j.end_obj();
  }
  if (cg_sd_tind_setup_present) {
    j.start_obj();
    j.write_int("id", 589);
    j.write_str("criticality", "reject");
    j.write_str("extensionValue", "true");
    j.end_obj();
  }
  j.end_array();
}

