      break;
    case types::uac_operator_defined:
      HANDLE_CODE(c.get<uac_operator_defined_s>().unpack(bref));
      break;
    case types::choice_ext:
      HANDLE_CODE(c.get<protocol_ie_single_container_s<uac_category_type_ext_ies_o>>().unpack(bref));
