crit_e uac_plmn_item_ext_ies_o::get_crit(const uint32_t& id)
{
  if (id == 385) {
    return crit_e::ignore;
  }
  asn1::log_error("The id={} is not recognized", id);
  return {};
}
presence_e uac_plmn_item_ext_ies_o::get_presence(const uint32_t& id)
{
  if (id == 385) {
    return presence_e::optional;
  }
  asn1::log_error("The id={} is not recognized", id);
  return {};
}

OCUDUASN_CODE uac_plmn_item_ext_ies_container::pack(bit_ref& bref) const
{
  uint32_t nof_ies = 0;
  nof_ies += n_id_present ? 1 : 0;
  HANDLE_CODE(pack_length(bref, nof_ies, 1u, 65535u, true));

  if (n_id_present) {
    HANDLE_CODE(pack_ie(bref, 385, crit_e{crit_e::ignore}, [this, &bref]() { return n_id.pack(bref); }));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE uac_plmn_item_ext_ies_container::unpack(cbit_ref& bref)
{
  uint32_t nof_ies = 0;
  HANDLE_CODE(unpack_length(nof_ies, bref, 1u, 65535u, true));

  for (; nof_ies > 0; --nof_ies) {
    uint32_t id;
    crit_e   crit;
    HANDLE_CODE(unpack_ie_header(bref, id, crit, &uac_plmn_item_ext_ies_o::get_crit));

    if (id == 385) {
      {
        n_id_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() { return n_id.unpack(bref); }));
      }
    } else {
      HANDLE_CODE(skip_ignored_ie(bref, crit, id));
    }
  }

  return OCUDUASN_SUCCESS;
}
void uac_plmn_item_ext_ies_container::to_json(json_writer& j) const
{
  j.start_array();
  if (n_id_present) {
    j.start_obj();
    j.write_int("id", 385);
    j.write_str("criticality", "ignore");
    j.write_fieldname("extensionValue");
    n_id.to_json(j);
    j.end_obj();
  }
  j.end_array();
}

