{
  j.start_array();
  if (source_mrb_id_present) {
    j.start_obj();
    j.write_int("id", 671);
    j.write_str("criticality", "ignore");
    j.write_int("extensionValue", source_mrb_id);
    j.end_obj();
  }
  j.end_array();
}

