// UEReportingInformation-ExtIEs ::= OBJECT SET OF F1AP-PROTOCOL-EXTENSION
uint32_t ue_report_info_ext_ies_o::idx_to_id(uint32_t idx)
{
  static const uint32_t names[] = {851};
  return map_enum_number(names, 1, idx, "id");
}
bool ue_report_info_ext_ies_o::is_id_valid(const uint32_t& id)
{
  return 851 == id;
}
crit_e ue_report_info_ext_ies_o::get_crit(const uint32_t& id)
{
  if (id == 851) {
    return crit_e::ignore;
  }
  asn1::log_error("The id={} is not recognized", id);
  return {};
}
presence_e ue_report_info_ext_ies_o::get_presence(const uint32_t& id)
{
  if (id == 851) {
    return presence_e::optional;
  }
  asn1::log_error("The id={} is not recognized", id);
  return {};
}

OCUDUASN_CODE ue_report_info_ext_ies_container::pack(bit_ref& bref) const
{
  uint32_t nof_ies = 0;
  nof_ies += report_interv_i_ms_present ? 1 : 0;
  HANDLE_CODE(pack_length(bref, nof_ies, 1u, 65535u, true));

  if (report_interv_i_ms_present) {
    HANDLE_CODE(pack_ie(bref, 851, crit_e{crit_e::ignore}, [this, &bref]() {
      return pack_integer(bref, report_interv_i_ms, (uint16_t)1u, (uint16_t)999u, false, true);
    }));
  }

  return OCUDUASN_SUCCESS;
}
OCUDUASN_CODE ue_report_info_ext_ies_container::unpack(cbit_ref& bref)
{
  uint32_t nof_ies = 0;
  HANDLE_CODE(unpack_length(nof_ies, bref, 1u, 65535u, true));

  for (; nof_ies > 0; --nof_ies) {
    uint32_t id;
    crit_e   crit;
    HANDLE_CODE(unpack_ie_header(bref, id, crit, &ue_report_info_ext_ies_o::get_crit));

    if (id == 851) {
      {
        report_interv_i_ms_present = true;
        HANDLE_CODE(unpack_ie_value(bref, [this, &bref]() {
          return unpack_integer(report_interv_i_ms, bref, (uint16_t)1u, (uint16_t)999u, false, true);
        }));
      }
    } else {
      HANDLE_CODE(skip_ignored_ie(bref, crit, id));
    }
  }

  return OCUDUASN_SUCCESS;
}
void ue_report_info_ext_ies_container::to_json(json_writer& j) const
{
  j.start_array();
  if (report_interv_i_ms_present) {
    j.start_obj();
    j.write_int("id", 851);
    j.write_str("criticality", "ignore");
    j.write_int("extensionValue", report_interv_i_ms);
    j.end_obj();
  }
  j.end_array();
}

